class NoVertexClickedError extends Error {
}
class Util {
    static pointToVector(point) {
        return [point.x, point.y];
    }
    static vectorToPoint(vector) {
        return { x: vector[0], y: vector[1] };
    }
    static getDistance(v1, v2) {
        return Math.sqrt(Math.pow(v1[0] - v2[0], 2) +
            Math.pow(v1[1] - v2[1], 2));
    }
    static getDistanceFromPoints(start, end) {
        return Math.sqrt(Math.pow(start.x - end.x, 2) +
            Math.pow(start.y - end.y, 2));
    }
    static getDistanceSquaredFromPoints(start, end) {
        return Math.pow(start.x - end.x, 2) + Math.pow(start.y - end.y, 2);
    }
    static getDirectionVectorNormalized(from_, to) {
        const d = this.getDistance(from_, to);
        return [(to[0] - from_[0]) / d, (to[1] - from_[1]) / d];
    }
    static getDirectionVectorNormalizedFromPoints(from_, to) {
        return this.getDirectionVectorNormalized(this.pointToVector(from_), this.pointToVector(to));
    }
    static scalarVectorMultiply(factor, v) {
        return [v[0] * factor, v[1] * factor];
    }
    static vectorAdd(v1, v2) {
        return [v1[0] + v2[0], v1[1] + v2[1]];
    }
    static getNormalized(v) {
        return this.scalarVectorMultiply(1 / this.getDistance(v, [0, 0]), v);
    }
}


